753	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate), do
754	            //     NOT write the loss (keep the first-pass loss), and assemble into
755	            //     `sam_grad` (NOT `grad`). `w` wraps `params` (now perturbed) so the tile
756	            //     fns read the perturbed weights with no re-bind needed.
757	            for (int i = threadIdx.x; i < vittc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
