760	                const int g0 = ti * nrows_tile;
761	                const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
762	                vittc::vittc_forward_tile(w, g0, nrows, acts, sc, in.patches, in.targets,
763	                                          sm.sA, sm.sB, sm.red);
