790	            //     LookSAM → sam_dir = g_sam − g; SuperGrok11/15 → sharpness = (g_sam − g)².
791	            {
792	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
793	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
