922	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
923	    //    2D weights (INTEGRATION-OPTSTAGES §3). For EACH 2D matrix (kVitMuon2D) all
924	    //    CTAs cooperate: buf=μ·buf+g (buf is the PERSISTENT m-slice — momentum state,
925	    //    NOT transient), ‖buf‖_F via per-CTA partials → inv_norm, X=buf·inv_norm,
926	    //    then ns_steps × { A=XXᵀ → AX=A·X → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap },
927	    //    then the canonical muon_update_step apply (decay·p + neg_lr_scale·orth). The
928	    //    1D / non-2D weights (cls_token, biases, LN γ/β) take the AdamW tail in P3.
929	    //    The elementwise bodies CALL muon.h (muon_momentum_normalize_step via the
930	    //    phaseA buf body, muon_ns_combine_step, muon_update_step); the matmuls are the
931	    //    cited new device code (the eager path delegates to torch::mm/cuBLAS). Guarded
932	    //    so every other opt is byte-identical (no extra barriers / work).
933	    if constexpr (Opt == OptId::Muon) {
934	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
935	        PrecomputeWorkspace pw{};
936	        pw.muon_X            = muon_base;
937	        pw.muon_AX           = pw.muon_X   + kVitMuonMaxNumel;
938	        pw.muon_AAX          = pw.muon_AX  + kVitMuonMaxNumel;
939	        pw.muon_orth         = pw.muon_AAX + kVitMuonMaxNumel;
940	        pw.muon_A            = pw.muon_orth + kVitMuonMaxNumel;
941	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)kVitMuonMaxRows * kVitMuonMaxRows;
942	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
943	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
944	        const int   ns_steps = 5;                 // bindings.cpp default
945	        for (int mi = 0; mi < vittc::kVitNumMuon2D; ++mi) {
946	            const vittc::VitMuon2D M = vittc::kVitMuon2D[mi];
947	            const int rows = M.rows, cols = M.cols;
948	            const int64_t numel = (int64_t)rows * cols;
949	            const int64_t off   = (int64_t)kVitOffsets[M.tidx];
950	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
951	            pw.muon_buf = st.exp_avg + off;
952	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
953	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
954	            bar.sync();
955	            muon_norm_reduce_phaseB(ctx, pw);
956	            bar.sync();
957	            muon_scale_X(numel, pw);
958	            bar.sync();
959	            // NS iterations. After each combine, orth holds the new iterate; swap so
960	            // the next iteration reads it as X. ns_steps swaps → final result is in
961	            // muon_X iff ns_steps even else muon_orth (we track the parity below).
962	            for (int s = 0; s < ns_steps; ++s) {
963	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
964	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
965	                bar.sync();
966	                // AX = A X   (M=rows,N=cols,K=rows).
967	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
968	                bar.sync();
969	                // AAX = A (AX) (M=rows,N=cols,K=rows).
970	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
971	                bar.sync();
972	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
973	                bar.sync();
974	                // swap X <-> orth (next iter reads X; final result tracked by parity).
975	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
976	            }
977	            // After ns_steps swaps the final orthogonalized matrix is in muon_X (the
978	            // last combine wrote muon_orth, then we swapped → muon_X). Apply Muon:
979	            //   p = decay_factor·p + neg_lr_scale·orth   (muon.h:63-73)
980	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
981	            const float neg_lr_scale = -lr * scale;
982	            const float decay_factor = 1.0f - lr * st.wd;
983	            float* __restrict__ p = params + off;
984	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
985	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
986	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
987	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
988	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
989	        }
990	    }
