1139	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
1140	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas);
1141	// any cap is hang-safe as long as the workspace + dW-tile/cls/pos ownership use
1142	// the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
1143	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
1144	// scratch (nCTA × slab) fits. Determinism is preserved per fixed nCTA.
1145	template <OptId Opt>
1146	cudaError_t launch_fused_vit_megakernel_tc(
1147	        PersistentContext ctx, float* params, ViTInputCtx in,
1148	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1149	        int ncta_cap = 0) {
1150	    int dev = 0;
1151	    cudaError_t err = cudaGetDevice(&dev);
1152	    if (err != cudaSuccess) return err;
1153	    int n_sms = 0;
1154	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1155	    if (err != cudaSuccess) return err;
1156	
1157	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
1158	    // (0 here — VitTcSmem is static). If the static smem + 200-reg consumer can't
1159	    // place one block/SM, REFUSE (the grid barrier would hang).
1160	    int occ = 0;
1161	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1162	        &occ, (const void*)&fused_vit_megakernel_tc<Opt>, SG_VIT_TC_MEGA_BLOCK,
1163	        /*dynamicSMemBytes=*/0);
1164	    if (err != cudaSuccess) return err;
1165	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1166	
1167	    unsigned launch_ctas = (unsigned)n_sms;
1168	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1169	    ctx.n_ctas = launch_ctas;
1170	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms).
1171	    if ((in.B % 16) != 0) return cudaErrorInvalidValue;
1172	
1173	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1174	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1175	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1176	
1177	    dim3 grid(launch_ctas), block(SG_VIT_TC_MEGA_BLOCK);
1178	    fused_vit_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
1179	        ctx, params, in, grad, lr, step, st);
1180	    return cudaGetLastError();
1181	}
