177	// Bind VitWeights to the flat params using the generated element offsets. The
178	// offsets array (csrc/fused/sm_90/vit_layout.cuh::kVitOffsets) is the C++ mirror
179	// of tests/hw/vit_oracle.py::vit_param_layout(), static-asserted.
180	__device__ __forceinline__ VitWeights vit_bind(const float* p) {
181	    VitWeights w;
182	    int i = 0;
183	    w.cls     = p + kVitOffsets[i++];
184	    w.patch_w = p + kVitOffsets[i++];
185	    w.patch_b = p + kVitOffsets[i++];
186	    w.pos     = p + kVitOffsets[i++];
187	    for (int li = 0; li < vit::kLayers; ++li) {
188	        w.layer[li].in_w  = p + kVitOffsets[i++];
189	        w.layer[li].in_b  = p + kVitOffsets[i++];
190	        w.layer[li].out_w = p + kVitOffsets[i++];
191	        w.layer[li].out_b = p + kVitOffsets[i++];
192	        w.layer[li].n1_w  = p + kVitOffsets[i++];
193	        w.layer[li].n1_b  = p + kVitOffsets[i++];
194	        w.layer[li].n2_w  = p + kVitOffsets[i++];
195	        w.layer[li].n2_b  = p + kVitOffsets[i++];
196	        w.layer[li].ff0_w = p + kVitOffsets[i++];
197	        w.layer[li].ff0_b = p + kVitOffsets[i++];
198	        w.layer[li].ff2_w = p + kVitOffsets[i++];
199	        w.layer[li].ff2_b = p + kVitOffsets[i++];
200	    }
201	    w.norm_w = p + kVitOffsets[i++];
202	    w.norm_b = p + kVitOffsets[i++];
203	    w.out_w  = p + kVitOffsets[i++];
204	    w.out_b  = p + kVitOffsets[i++];
205	    return w;
206	}
