208	// Identical helper for the per-CTA grad PARTIAL buffer (writable, same layout).
209	struct VitGrad {
210	    float* cls; float* patch_w; float* patch_b; float* pos;
211	    struct Layer { float* in_w; float* in_b; float* out_w; float* out_b;
212	        float* n1_w; float* n1_b; float* n2_w; float* n2_b;
213	        float* ff0_w; float* ff0_b; float* ff2_w; float* ff2_b; } layer[vit::kLayers];
214	    float* norm_w; float* norm_b; float* out_w; float* out_b;
215	};
216	__device__ __forceinline__ VitGrad vit_bind_grad(float* p) {
217	    VitGrad w; int i = 0;
218	    w.cls     = p + kVitOffsets[i++];
219	    w.patch_w = p + kVitOffsets[i++];
220	    w.patch_b = p + kVitOffsets[i++];
221	    w.pos     = p + kVitOffsets[i++];
222	    for (int li = 0; li < vit::kLayers; ++li) {
223	        w.layer[li].in_w  = p + kVitOffsets[i++];
224	        w.layer[li].in_b  = p + kVitOffsets[i++];
225	        w.layer[li].out_w = p + kVitOffsets[i++];
226	        w.layer[li].out_b = p + kVitOffsets[i++];
227	        w.layer[li].n1_w  = p + kVitOffsets[i++];
228	        w.layer[li].n1_b  = p + kVitOffsets[i++];
229	        w.layer[li].n2_w  = p + kVitOffsets[i++];
230	        w.layer[li].n2_b  = p + kVitOffsets[i++];
231	        w.layer[li].ff0_w = p + kVitOffsets[i++];
232	        w.layer[li].ff0_b = p + kVitOffsets[i++];
233	        w.layer[li].ff2_w = p + kVitOffsets[i++];
234	        w.layer[li].ff2_b = p + kVitOffsets[i++];
235	    }
236	    w.norm_w = p + kVitOffsets[i++];
237	    w.norm_b = p + kVitOffsets[i++];
238	    w.out_w  = p + kVitOffsets[i++];
239	    w.out_b  = p + kVitOffsets[i++];
240	    return w;
241	}
