292	// ────────────────────────────────────────────────────────────────────────────
293	//  Primitive in-kernel ops, CTA-cooperative over one sample. Inputs/outputs are
294	//  smem [n_rows, width] tiles. Threads stride over the (row, feature) grid.
295	//  These mirror the oracle's primitive ops exactly.
296	// ────────────────────────────────────────────────────────────────────────────
297	
298	// y[s, :out] = x[s, :in] @ W[out, in]^T + b[out], for s in [0,n_rows). W row-major.
299	__device__ __forceinline__ void vit_linear(
300	        const float* __restrict__ x, int in_dim,
301	        const float* __restrict__ W, const float* __restrict__ b, int out_dim,
302	        float* __restrict__ y, int n_rows) {
303	    const int total = n_rows * out_dim;
304	    for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
305	        const int s = idx / out_dim;
306	        const int o = idx % out_dim;
307	        const float* xr = x + s * in_dim;
308	        const float* Wr = W + (int64_t)o * in_dim;
309	        float acc = (b != nullptr) ? b[o] : 0.0f;
310	        #pragma unroll 4
311	        for (int k = 0; k < in_dim; ++k) acc += xr[k] * Wr[k];
312	        y[s * out_dim + o] = acc;
313	    }
314	    __syncthreads();
315	}
316	
317	// LayerNorm forward over the last dim (width=d). Caches xhat + inv_std for bwd.
318	__device__ __forceinline__ void vit_layernorm_fwd(
319	        const float* __restrict__ x, const float* __restrict__ gamma,
320	        const float* __restrict__ beta, float* __restrict__ y,
321	        float* __restrict__ xhat_out, float* __restrict__ inv_out, float* red) {
322	    for (int s = 0; s < vit::kSeq; ++s) {
323	        const float* xr = x + s * vit::kD;
324	        float sum = 0.0f;
325	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += xr[j];
326	        float mean = vit_block_sum(sum, red) / (float)vit::kD;
327	        float vs = 0.0f;
328	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
329	            float c = xr[j] - mean; vs += c * c;
330	        }
331	        float var = vit_block_sum(vs, red) / (float)vit::kD;
332	        float inv = rsqrtf(var + vit::kLnEps);
333	        if (threadIdx.x == 0) inv_out[s] = inv;
334	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
335	            float xh = (xr[j] - mean) * inv;
336	            xhat_out[s * vit::kD + j] = xh;
337	            y[s * vit::kD + j] = xh * gamma[j] + beta[j];
338	        }
339	        __syncthreads();
340	    }
341	}
